   covergroup axi_delay_cg with function sample(int index);
      option.per_instance = 0;
      option.goal = 100;
      option.name = "AXI_Delay_Coverage";
   //cover all coverpoints when index 0. for index>0 cover array values only.
     cmd2cmd_delay : coverpoint cmd2cmd iff(index == 0){
                     bins delay_0 ={0};
                     bins delay_1 ={1};
                     bins delay_2 ={2};
                     bins delay_3 ={3};
                     bins delay_4_15 ={[4:15]};
                     bins delay_16_100 ={[16:100]};
                     bins delay_100_1k ={[100:1000]};
     }
     data2data_delay : coverpoint data2data[index] {
                     bins delay_0 ={0};
                     bins delay_1 ={1};
                     bins delay_2 ={2};
                     bins delay_3 ={3};
                     bins delay_4_15 ={[4:15]};
                     bins delay_16_100 ={[16:100]};
                     bins delay_100_1k ={[100:1000]};
     }
     cmd2data_delay : coverpoint cmd2data iff(index == 0){
