                     bins delay_100_1k ={[100:1000]};
     }

   endgroup

   covergroup axi_ic_xbar_cg;
      option.per_instance = 0;
      option.goal = 100;
      option.name = "AXI_Interconnect_Xbar_Coverage";

     target_master : coverpoint mas_idx {
                     bins master1 ={0};
                     bins master2 ={1};
                     bins master3 ={2};
                     bins master4 ={3};
     }
     target_slave : coverpoint slv_idx {
                    bins slave1 ={0};
                    bins slave2 ={1};
                    bins slave3 ={2};
                    bins slave4 ={3};
     }
     address_decoding : cross target_master,target_slave; //to cover every master accessed every slave
   endgroup

   covergroup axi_ic_feature_cg;
      option.per_instance = 0;
      option.goal = 100;
      option.name = "AXI_Interconnect_Feature_Coverage";

      address_alignment : coverpoint add_aligned {
                          bins aligned_address ={1};
                          bins unaligned_address ={0};
      }
      packet_split : coverpoint split {
                     bins no_split ={0};
                     bins split    ={1};
      }
      request_size : coverpoint req_size {
                      bins bits_32  ={2};
                      bins bits_64  ={3};
                      bins bits_128 ={4};
                      bins bits_256 ={5};
      }
      response_size : coverpoint resp_size {
                      bins bits_32  ={2};
                      bins bits_64  ={3};
                      bins bits_128 ={4};
                      bins bits_256 ={5};
      }
      data_width_conversion : cross request_size,response_size; //to cover all possible conversions
   endgroup

   function new(string name ="axi_cdma_axi_coverage");
     super.new(name);
     axi_cg = new();
     axi_delay_cg =new();
     axi_ic_xbar_cg=new();
     axi_ic_feature_cg=new();
   endfunction


   function void sample_delays(input previous_cmd_ts, axi_cdma_axi_base_seq_item pkt);
      int clk_p =10; //clk period // later shift this to top or parameters
      cmd2cmd = (pkt.operation==WRITE) ? (pkt.wadd_hndshk - previous_cmd_ts)/clk_p : (pkt.radd_hndshk - previous_cmd_ts)/clk_p;
      if(pkt.operation==WRITE) data2data = new[pkt.awlen +1];
      else data2data = new[pkt.arlen +1];
      data2data[0] = 0;
      for(int i = 1; i<=data2data.size(); i++)
      data2data[i] = (pkt.operation==WRITE) ? (pkt.wdata_hndshk[i-1] -pkt.wdata_hndshk[i])/clk_p : (pkt.rdata_hndshk[i-1] -pkt.rdata_hndshk[i])/clk_p;
      cmd2data = (pkt.operation==WRITE) ? ((pkt.wdata_hndshk[0]-pkt.wadd_hndshk)/clk_p) : ((pkt.rdata_hndshk[0]-pkt.radd_hndshk)/clk_p);
      data2resp = (pkt.operation==WRITE) ? (pkt.wdata_hndshk[pkt.awlen]-pkt.wresp_hndshk)/clk_p : 0;
      cmd2resp = (pkt.operation==WRITE) ? (pkt.wresp_hndshk - pkt.wadd_hndshk)/clk_p : (pkt.rdata_hndshk[pkt.arlen] -pkt.radd_hndshk)/clk_p;
      if(pkt.operation==WRITE)
      foreach(pkt.wdata[i]) axi_delay_cg.sample(i);
      else foreach(pkt.rdata[i]) axi_delay_cg.sample(i);
  endfunction

  function void sample_address_decoding(input int master_index,slave_index);
     mas_idx =master_index;
     slv_idx =slave_index;
     axi_ic_xbar_cg.sample();
  endfunction

  function void sample_axi_features(input int align_adjustment,no_of_split_packets,master_size,slave_size);
     add_aligned =(align_adjustment==0)? 0 : 1; //for add_alignment axi_cdma_axi_coverage
     split =(no_of_split_packets >1)? 1 :0;
     req_size = master_size;
     resp_size = slave_size;
     axi_ic_feature_cg.sample();
  endfunction

endclass
